operation.add:
require_once(DIR_TEMPLATE . '../../../catalog/view/theme/evrika/php/icons.php');

$list = array();

$categories = $this->model_catalog_category->getCategories(0);

foreach ($categories as $category) {
	$filter_data = array(
		'filter_category_id'  => $category['category_id'],
		'filter_sub_category' => true,
	);

	$total = $this->model_catalog_product->getTotalProducts($filter_data);

	$list[] = array(
		'category_id' => $category['category_id'],
		'name'        => $category['name'],
		'icon_svg'    => evrika_icon_svg(isset($category['icon']) ? $category['icon'] : ''),
		'total'       => $total,
		'total_label' => evrika_plural_products($total),
		'href'        => $this->url->link('product/category', 'path=' . $category['category_id']),
	);
}

usort($list, function($a, $b) { return $b['total'] - $a['total']; });

$data['categories'] = array_slice($list, 0, 6);

return $this->load->view('extension/module/category', $data);

